# Compare two process directories (e.g. one generated by genProc.sh and a
# reference one). By default all files are compared, skipping binaries, html,
# logs and python caches (ALOHA writes the declarations of the HELAS routines
# in a random order: files in Source/DHELAS that only differ by the order of
# lines are not reported). With -touched <base>, only the files of <refdir>
# changed in git (working tree) since commit <base> are compared, skipping
# run outputs, cards and dev scripts (e.g. for the hand-written eebbbb_vfalt,
# whose generated baseline is 1bdfca9909), and the source files that only
# exist in <gendir> are listed. With -diff, the differences of each file that
# differs are also printed line by line (diff -u).

set -e
set -o pipefail

usage() {
  echo "Usage:   $0 [-touched <base>] [-diff] <refdir> <gendir>"
  echo "         (<refdir> and <gendir> relative to the current or the mg5amcnlo directory)"
  echo "Example: $0 /tmp/eebbbb_stock madvfold/DEV/eebbbb_vfgen"
  echo "Example: $0 -touched 1bdfca9909 madvfold/DEV/eebbbb_vfalt madvfold/DEV/eebbbb_vfgen"
  echo "Example: $0 -touched 1bdfca9909 -diff madvfold/DEV/eebbbb_vfalt madvfold/DEV/eebbbb_vfgen | less"
  exit 1
}
base=
showdiff=0
while [ "$1" != "" ]; do
  if [ "$1" == "-touched" ] && [ "$#" -ge 2 ]; then base=$2; shift 2
  elif [ "$1" == "-diff" ]; then showdiff=1; shift
  elif [ "${1:0:1}" == "-" ]; then usage
  else break; fi
done
if [ "$1" == "" ] || [ "$2" == "" ] || [ "$3" != "" ]; then usage; fi
# The directories may be given relative to the current directory or to the
# mg5amcnlo directory (as in the examples above): use their absolute paths
mg5dir=$(cd $(dirname $0)/../..; pwd -P)
absdir() {
  if [ -d "$1" ]; then (cd "$1"; pwd -P)
  elif [ -d "${mg5dir}/$1" ]; then (cd "${mg5dir}/$1"; pwd -P)
  else echo "ERROR! Directory not found: $1" 1>&2; exit 1; fi
}
ref=$(absdir $1)
gen=$(absdir $2)

if [ "${base}" == "" ]; then
  # Compare all files
  echo "=== diff -r ${ref} ${gen}"
  nfull=0; nhelas=0
  while read -r line; do
    f=$(echo "${line}" | awk '{print $2}'); f=${f#${ref}/}
    if [ "${f#Source/DHELAS/}" != "${f}" ] && [ -f ${ref}/${f} ] && [ -f ${gen}/${f} ] \
      && cmp -s <(sort ${ref}/${f}) <(sort ${gen}/${f}); then nhelas=$((nhelas+1)); continue; fi
    echo "${line}"; nfull=$((nfull+1))
    if [ "${showdiff}" == "1" ] && [ -f ${ref}/${f} ] && [ -f ${gen}/${f} ]; then diff -u ${ref}/${f} ${gen}/${f} || true; fi
  done < <(diff -rq --no-dereference -x '*.pyc' -x __pycache__ -x '*.html' -x '*.jpg' -x '*.ps' -x '*.log' -x GENLOG.txt \
    -x '*.o' -x '*.a' -x '*.mod' -x '*.so' -x '*.tar.gz' ${ref} ${gen} || true)
  echo "=== ${ref} vs ${gen}: ${nfull} differences (plus ${nhelas} DHELAS files differing only by the order of lines)"
  exit 0
fi

# Compare the files of ${ref} changed in git since ${base}
refgit=$(cd ${ref}; git rev-parse --show-prefix); refgit=${refgit%/}
files=$(cd ${ref}; git diff --name-only --relative ${base} -- . \
  | grep -v -E '^(Events/|Cards/|GEN_|vfold/GEN_|\.gitignore)' \
  | grep -v -E '(fort\.7[78]|reweight_xsec_events)$' || true)
nsame=0; ndiff=0; nmiss=0
for f in ${files}; do
  if [ ! -e ${ref}/${f} ]; then continue; fi # removed from ref since the baseline
  if [ ! -e ${gen}/${f} ]; then echo "MISSING in gen: ${f}"; nmiss=$((nmiss+1))
  elif ! cmp -s ${ref}/${f} ${gen}/${f}; then echo "DIFFERS:        ${f} ($(diff ${ref}/${f} ${gen}/${f} | grep -c '^[<>]') lines)"; ndiff=$((ndiff+1))
    if [ "${showdiff}" == "1" ]; then diff -u ${ref}/${f} ${gen}/${f} || true; fi
  else nsame=$((nsame+1)); fi
done
# Source files that exist only in gen (e.g. new vfold files not in ref)
nonly=0
for f in $(cd ${gen}; find SubProcesses Source bin -type f \( -name '*.f' -o -name '*.f90' -o -name '*.inc' -o -name '*.c' -o -name '*.cc' -o -name '*.cpp' -o -name '*.h' -o -name '*.py' -o -name 'make*' \) | sort); do
  if [ ! -e ${ref}/${f} ]; then echo "ONLY in gen:    ${f}"; nonly=$((nonly+1)); fi
done
echo "=== ${ref} vs ${gen}: ${nsame} identical, ${ndiff} differ, ${nmiss} missing in gen (of $(echo ${files} | wc -w) files touched since ${base}), ${nonly} source files only in gen"
